import { useForm } from '@octanejs/hook-form';

interface Profile {
	name: string;
	email: string;
}

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function App(props: { onSave: (profile: Profile) => void }) @{
	const {
		register,
		handleSubmit,
		formState: { errors },
	} = useForm<Profile>({ mode: 'onChange' });
	const submit = handleSubmit((profile) => props.onSave(profile));

	<form onSubmit={submit} noValidate>
		<h1>Edit profile</h1>
		<label for="name">Name</label>
		<input id="name" {...register('name', { required: 'Name is required' })} />
		@if (errors.name) {
			<p role="alert">{errors.name.message as string}</p>
		}

		<label for="email">Email</label>
		<input
			id="email"
			type="email"
			{...register('email', {
				required: 'Email is required',
				pattern: { value: EMAIL_PATTERN, message: 'Enter a valid email' },
			})}
		/>
		@if (errors.email) {
			<p role="alert">{errors.email.message as string}</p>
		}

		<button type="submit">Save profile</button>
	</form>
}

import { I18nextProvider, Trans, useTranslation } from '@octanejs/i18next';
import type { i18n } from 'i18next';

function LocalizedContent(props: { name: string }) @{
	const { t, i18n } = useTranslation('translation', { useSuspense: false });

	<section>
		<h1>{t('greeting', { name: props.name }) as string}</h1>
		<p>
			<Trans i18nKey="details" components={{ strong: <strong /> }} />
		</p>
		<button aria-pressed={i18n.resolvedLanguage === 'en'} onClick={() => i18n.changeLanguage('en')}>
			English
		</button>
		<button aria-pressed={i18n.resolvedLanguage === 'fr'} onClick={() => i18n.changeLanguage('fr')}>
			French
		</button>
	</section>
}

export function App(props: { i18n: i18n; name: string }) @{
	<I18nextProvider i18n={props.i18n} defaultNS="translation">
		<LocalizedContent name={props.name} />
	</I18nextProvider>
}

# Build a TanStack Query user card

Implement `App` in `src/App.tsrx` with `@octanejs/tanstack-query`.

`App` receives a `QueryClient`, a `userId`, and an injected
`loadUser(userId)` function. Provide the client with `QueryClientProvider` and
load the user with `useQuery`. Use a query key that includes the current user
ID so changing `userId` loads and displays the new user. Disable retries.

While unresolved, render `Loading user…` with `role="status"`. On success,
render the user's name as a heading and their email. On failure, render
`Could not load user: message` with `role="alert"`. Do not call the loader
outside the query, create a replacement client, or mirror query data into local
state. Only edit `src/App.tsrx`.

Starter src/App.tsrx:

```tsx
import type { QueryClient } from '@octanejs/tanstack-query';

export interface User {
	id: string;
	name: string;
	email: string;
}

export function App(_props: {
	client: QueryClient;
	userId: string;
	loadUser: (userId: string) => Promise<User>;
}) @{
	<section aria-label="User card">
		<p role="status">Loading user…</p>
	</section>
}
```

import { QueryClientProvider, useQuery } from '@octanejs/tanstack-query';
import type { QueryClient } from '@octanejs/tanstack-query';

export interface User {
	id: string;
	name: string;
	email: string;
}

interface UserCardProps {
	userId: string;
	loadUser: (userId: string) => Promise<User>;
}

function UserCard(props: UserCardProps) @{
	const query = useQuery({
		queryKey: ['user', props.userId],
		queryFn: () => props.loadUser(props.userId),
		retry: false,
	});

	<section aria-label="User card">
		@if (query.isPending) {
			<p role="status">Loading user…</p>
		} @else if (query.isError) {
			<p role="alert">{'Could not load user: ' + (query.error as Error).message}</p>
		} @else {
			<>
				<h1>{query.data.name as string}</h1>
				<p>{query.data.email as string}</p>
			</>
		}
	</section>
}

export function App(props: {
	client: QueryClient;
	userId: string;
	loadUser: (userId: string) => Promise<User>;
}) @{
	<QueryClientProvider client={props.client}>
		<UserCard userId={props.userId} loadUser={props.loadUser} />
	</QueryClientProvider>
}

import { create } from '@octanejs/zustand';

const products = [
	{ id: 'coffee', name: 'Coffee', priceCents: 1250 },
	{ id: 'tea', name: 'Tea', priceCents: 500 },
] as const;

type ProductId = (typeof products)[number]['id'];

interface CartState {
	quantities: Partial<Record<ProductId, number>>;
	add: (id: ProductId) => void;
	decrease: (id: ProductId) => void;
	clear: () => void;
}

const useCartStore = create<CartState>((set) => ({
	quantities: {},
	add: (id) =>
		set((state) => ({
			quantities: {
				...state.quantities,
				[id]: (state.quantities[id] ?? 0) + 1,
			},
		})),
	decrease: (id) =>
		set((state) => {
			const quantities = { ...state.quantities };
			const next = (quantities[id] ?? 0) - 1;
			if (next > 0) quantities[id] = next;
			else delete quantities[id];
			return { quantities };
		}),
	clear: () => set({ quantities: {} }),
}));

function formatPrice(cents: number): string {
	return '£' + (cents / 100).toFixed(2);
}

export function App() @{
	const quantities = useCartStore((state) => state.quantities);
	const add = useCartStore((state) => state.add);
	const decrease = useCartStore((state) => state.decrease);
	const clear = useCartStore((state) => state.clear);
	const lines = products.filter((product) => (quantities[product.id] ?? 0) > 0);
	const total = products.reduce(
		(sum, product) => sum + product.priceCents * (quantities[product.id] ?? 0),
		0,
	);

	<main>
		<h1>Shopping cart</h1>
		<div>
			@for (const product of products; key product.id) {
				<button aria-label={'Add ' + product.name} onClick={() => add(product.id)}>
					{'Add ' + product.name}
				</button>
			}
		</div>
		@if (lines.length === 0) {
			<p>Cart empty</p>
		} @else {
			<ul>
				@for (const product of lines; key product.id) {
					<li>
						<span>{product.name + ' × ' + (quantities[product.id] ?? 0)}</span>
						<button aria-label={'Decrease ' + product.name} onClick={() => decrease(product.id)}>
							{'Decrease ' + product.name}
						</button>
					</li>
				}
			</ul>
		}
		<p>{'Total: ' + formatPrice(total)}</p>
		<button disabled={lines.length === 0} onClick={clear}>
			Clear cart
		</button>
	</main>
}

import { use } from 'octane';

export interface Product {
	id: string;
	name: string;
	priceCents: number;
}

export function App(props: { productId: string; loadProduct: (id: string) => Promise<Product> }) @{
	<section aria-label="Product details">
		@try {
			const product = use(props.loadProduct(props.productId));
			<article class="product" data-product-id={product.id}>
				<h2>{product.name as string}</h2>
				<p class="price">{'$' + (product.priceCents / 100).toFixed(2)}</p>
			</article>
		} @pending {
			<p class="loading">Loading product…</p>
		} @catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			<p class="error" role="alert">
				{message as string}
			</p>
		}
	</section>
}

# Compose a keyed team board

Create `src/App.tsrx` as a small team-recognition board. Keep these exports:

- the `Member` interface;
- the `MemberCard` component;
- the `TeamSummary` component; and
- the `App` component.

The board has two members in this initial order:

1. Ada — bio `Designs accessible systems`
2. Grace — bio `Operates cloud services`

Implement the following behavior:

- `App` owns each member's applause count, initially zero, and passes the
  current count and an update callback into each `MemberCard`.
- Each card owns whether its bio is open as local `useState` state. Its button
  is named `Show details NAME` while closed and `Hide details NAME` while open.
  Render the bio with TSRX `@if` only while open.
- Each card has a button named `Applaud twice NAME`. One native click must call
  the parent callback twice. Use a functional parent state update so both
  updates are retained even though they happen in one event handler.
- Render each count in an `<output>` named `Applause NAME`.
- Compose a `TeamSummary` that receives the total and renders it in an
  `<output>` named `Total applause`.
- Add a `Reverse team` button. Render the cards using keyed TSRX `@for`, keyed
  by member ID, so reversing the array preserves each card's DOM identity and
  local details state.

Use native `onClick` handlers and keep all implementation code in
`src/App.tsrx`. Do not add dependencies or modify the grader.

Starter src/App.tsrx:

```tsx
export interface Member {
	id: string;
	name: string;
	bio: string;
}

export function MemberCard(props: {
	member: Member;
	applause: number;
	onApplaud: (id: string) => void;
}) @{
	<article data-member-id={props.member.id}>
		<h2>{props.member.name as string}</h2>
		<output aria-label={'Applause ' + props.member.name}>{props.applause as string}</output>
		<button>{'Show details ' + props.member.name}</button>
		<button>{'Applaud twice ' + props.member.name}</button>
	</article>
}

export function TeamSummary(props: { total: number }) @{
	<output aria-label="Total applause">{props.total as string}</output>
}

export function App() @{
	<main>
		<h1>Team board</h1>
		<button>Reverse team</button>
		<TeamSummary total={0} />
	</main>
}
```

import { useState } from 'octane';

export interface Member {
	id: string;
	name: string;
	bio: string;
}

const members: Member[] = [
	{ id: 'ada', name: 'Ada', bio: 'Designs accessible systems' },
	{ id: 'grace', name: 'Grace', bio: 'Operates cloud services' },
];

export function MemberCard(props: {
	member: Member;
	applause: number;
	onApplaud: (id: string) => void;
}) @{
	const [detailsOpen, setDetailsOpen] = useState(false);

	<article data-member-id={props.member.id}>
		<h2>{props.member.name as string}</h2>
		<output aria-label={'Applause ' + props.member.name}>{props.applause as string}</output>
		<button
			aria-label={(detailsOpen ? 'Hide details ' : 'Show details ') + props.member.name}
			onClick={() => setDetailsOpen((open) => !open)}
		>
			{detailsOpen ? 'Hide details' : 'Show details'}
		</button>
		<button
			aria-label={'Applaud twice ' + props.member.name}
			onClick={() => {
				props.onApplaud(props.member.id);
				props.onApplaud(props.member.id);
			}}
		>
			Applaud twice
		</button>
		@if (detailsOpen) {
			<p>{props.member.bio as string}</p>
		}
	</article>
}

export function TeamSummary(props: { total: number }) @{
	<output aria-label="Total applause">{props.total as string}</output>
}

export function App() @{
	const [applause, setApplause] = useState<Record<string, number>>({ ada: 0, grace: 0 });
	const [reversed, setReversed] = useState(false);
	const orderedMembers = reversed ? [...members].reverse() : members;
	const total = Object.values(applause).reduce((sum, count) => sum + count, 0);
	const applaud = (id: string) => {
		setApplause((current) => ({
			...current,
			[id]: (current[id] ?? 0) + 1,
		}));
	};

	<main>
		<h1>Team board</h1>
		<button onClick={() => setReversed((value) => !value)}>Reverse team</button>
		<TeamSummary total={total} />
		<section aria-label="Team members">
			@for (const member of orderedMembers; key member.id) {
				<MemberCard member={member} applause={applause[member.id] ?? 0} onApplaud={applaud} />
			}
		</section>
	</main>
}

# Derive a live invoice with inferred hook dependencies

Implement `src/App.tsrx` and export a component named `App` with these props:

```ts
{
	quantity: number;
	unitPrice: number;
	discount: number;
	onTotal: (total: number) => void;
}
```

This task exercises Octane's compiler-inferred dependencies. In React, omitting
a dependency array makes an effect run after every render. In Octane, omission
asks the compiler to derive the dependencies from lexical captures.

Requirements:

- Compute `subtotal` as `quantity * unitPrice` with `useMemo`.
- Compute `total` as `Math.max(0, subtotal - discount)` with a second `useMemo`.
- Omit the dependency array from both `useMemo` calls. Do not manually write an
  array or pass `null`.
- Call `onTotal(total)` from a `useEffect`, also with its dependency array
  omitted. The effect must react to both the total and a replacement `onTotal`
  callback, while avoiding unrelated repeats.
- Render the quantity in an output labelled `Quantity`, the subtotal in an
  output labelled `Subtotal`, and the total in an output labelled `Total`.
- Format subtotal and total as fixed two-decimal strings without a currency
  symbol.

Keep all implementation code in `src/App.tsrx`. Do not add dependencies or edit
the grader.

Starter src/App.tsrx:

```tsx
import { useEffect, useMemo } from 'octane';

export function App(props: {
	quantity: number;
	unitPrice: number;
	discount: number;
	onTotal: (total: number) => void;
}) @{
	const subtotal = useMemo(() => props.quantity * props.unitPrice, []);
	const total = useMemo(() => Math.max(0, subtotal - props.discount), []);

	useEffect(() => {
		props.onTotal(total);
	}, []);

	<section aria-label="Invoice summary">
		<output aria-label="Quantity">{props.quantity as string}</output>
		<output aria-label="Subtotal">{subtotal.toFixed(2)}</output>
		<output aria-label="Total">{total.toFixed(2)}</output>
	</section>
}
```

import { useEffect, useMemo } from 'octane';

export function App(props: {
	quantity: number;
	unitPrice: number;
	discount: number;
	onTotal: (total: number) => void;
}) @{
	const subtotal = useMemo(() => props.quantity * props.unitPrice);
	const total = useMemo(() => Math.max(0, subtotal - props.discount));

	useEffect(() => {
		props.onTotal(total);
	});

	<section aria-label="Invoice summary">
		<output aria-label="Quantity">{props.quantity as string}</output>
		<output aria-label="Subtotal">{subtotal.toFixed(2)}</output>
		<output aria-label="Total">{total.toFixed(2)}</output>
	</section>
}

import { useState } from 'octane';

export function PreferenceField(props: { onChange: (value: string) => void }) @{
	<button type="button" onClick={() => props.onChange('compact')}>
		Choose compact
	</button>
}

export function App() @{
	const [title, setTitle] = useState('');
	const [savedDraft, setSavedDraft] = useState('Nothing committed yet');
	const [plan, setPlan] = useState('free');
	const [alerts, setAlerts] = useState(false);
	const [layout, setLayout] = useState('comfortable');
	const [alias, setAlias] = useState('');
	const aliasInputProps = {
		type: String('text'),
		value: alias,
		onInput: (event: Event) => setAlias((event.currentTarget as HTMLInputElement).value),
	};

	<main>
		<h1>Native event settings</h1>

		<label>
			Live title
			<input
				value={title}
				onInput={(event) => setTitle((event.currentTarget as HTMLInputElement).value)}
			/>
		</label>
		<output aria-label="Live title value">{title || 'Empty'}</output>

		<label>
			Draft note
			<input
				defaultValue="Initial draft"
				onChange={(event) => setSavedDraft((event.currentTarget as HTMLInputElement).value)}
				suppressNativeChangeWarning
			/>
		</label>
		<output aria-label="Last saved draft">{savedDraft}</output>

		<label>
			Plan
			<select
				value={plan}
				onChange={(event) => setPlan((event.currentTarget as HTMLSelectElement).value)}
			>
				<option value="free">Free</option>
				<option value="pro">Pro</option>
			</select>
		</label>
		<output aria-label="Selected plan">{plan === 'free' ? 'Free' : 'Pro'}</output>

		<label>
			<input
				type="checkbox"
				checked={alerts}
				onChange={(event) => setAlerts((event.currentTarget as HTMLInputElement).checked)}
			/>
			Email alerts
		</label>
		<output aria-label="Alert status">{alerts ? 'enabled' : 'disabled'}</output>

		<PreferenceField onChange={setLayout} />
		<output aria-label="Layout">{layout}</output>

		<label>
			Dynamic alias
			<input {...aliasInputProps} />
		</label>
		<output aria-label="Dynamic alias value">{alias || 'Empty'}</output>
	</main>
}

# Build a controlled search field with native input events

Implement `src/App.tsrx` and continue to export `SearchField` and `App`.

This task exercises an intentional Octane difference from React: text controls
use the browser's native `input` event. There is no synthetic `onChange`
normalization.

`SearchField` receives these props:

```ts
{
	id: string;
	value: string;
	onQueryInput: (value: string, event: Event) => void;
}
```

Requirements:

- Render a search input labelled `Search` using the supplied `id`.
- Make the input controlled by the `value` prop.
- Handle each edit with `onInput`, not `onChange`. Call `onQueryInput` with the
  input's live string value and the native `Event` object.
- If a parent does not accept an edit by supplying a new `value`, the controlled
  input must return to the supplied value after the event.
- `App` receives an `onQueryInput` prop with the same callback signature. It owns
  an initially empty query with `useState` and composes `SearchField`.
- `App` renders `Type to search` in a status element while empty and
  `Searching for: <query>` after edits.
- Render a `Clear search` button. It is disabled while empty and clears the
  controlled query when clicked.

Keep all implementation code in `src/App.tsrx`. Do not add dependencies or edit
the grader.

Starter src/App.tsrx:

```tsx
import { useState } from 'octane';

export function SearchField(props: {
	id: string;
	value: string;
	onQueryInput: (value: string, event: Event) => void;
}) @{
	<>
		<label htmlFor={props.id}>Search</label>
		<input
			id={props.id}
			type="search"
			defaultValue={props.value}
			onChange={(event) => props.onQueryInput((event.target as HTMLInputElement).value, event)}
		/>
	</>
}

export function App(props: { onQueryInput: (value: string, event: Event) => void }) @{
	const [query, setQuery] = useState('');
	const updateQuery = (value: string, event: Event) => {
		setQuery(value);
		props.onQueryInput(value, event);
	};

	<section>
		<SearchField id="search-query" value={query} onQueryInput={updateQuery} />
		<p role="status">{query ? 'Searching for: ' + query : 'Type to search'}</p>
		<button type="button" disabled={query.length === 0} onClick={() => setQuery('')}>
			Clear search
		</button>
	</section>
}
```

